<script setup lang="ts">
import {parseBackup,MAX_BACKUP_BYTES} from '#repositories/learning'
import {seoulDate} from '#shared/model'
const {state,ready,mode,busy,restore,clear,signOut,setReviewQuestionLimit}=useLearning(),message=ref(''),failed=ref(false),confirmDelete=ref(''),pending=ref<ReturnType<typeof parseBackup>|null>(null)
function report(e:unknown){failed.value=true;message.value=e instanceof Error?e.message:'처리하지 못했어요.'}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});if(blob.size>MAX_BACKUP_BYTES){report(new Error('기록이 10MB를 넘어 백업할 수 없어요. 데이터를 정리한 뒤 다시 시도해 주세요.'));return}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`afsr-math-${seoulDate()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);failed.value=false;message.value='백업 파일을 내보냈어요.'}
async function chooseFile(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>MAX_BACKUP_BYTES)throw new Error('10MB 이하의 JSON 파일을 선택해 주세요.');pending.value=parseBackup(await file.text());message.value='백업을 확인했어요. 아래에서 가져오기를 확정해 주세요.';failed.value=false}catch(e){pending.value=null;report(e)}finally{(event.target as HTMLInputElement).value=''}}
async function importData(){try{if(!pending.value)return;await restore(pending.value);pending.value=null;message.value='백업을 가져왔어요.';failed.value=false}catch(e){report(e)}}
async function deleteData(){if(confirmDelete.value!=='삭제')return;try{await clear();confirmDelete.value='';message.value='현재 저장소의 학습 데이터를 삭제했어요.';failed.value=false}catch(e){report(e)}}
</script>
<template><div class="page narrow-page"><div class="eyebrow">YOUR DATA, YOUR SPACE</div><h1>데이터 및 설정</h1><p class="page-intro">학습 기록을 안전하게 보관하고 관리해요.</p><p v-if="!ready" role="status" class="muted">저장한 데이터를 불러오고 있어요…</p><p v-if="message" role="status" :class="failed?'alert':'success-message'">{{message}}</p><section class="settings-section"><h2>저장 위치</h2><div class="storage-banner"><span class="storage-dot"/><div><b>{{mode==='loading'?'저장소 확인 중':mode==='local'?'이 기기 · IndexedDB':'클라우드 · Supabase PostgreSQL'}}</b><p>{{mode==='loading'?'저장 방식을 확인하고 있어요.':mode==='local'?'브라우저에 학습 기록을 저장하고 있어요.':'풀이 중에는 이 기기에, 학습 종료 시에는 Supabase에 저장해요.'}}</p></div><span class="status-tag">사용 중</span></div><p class="muted footnote">저장 위치는 서버 설정에 따라 자동으로 결정돼요. JSON 백업과 복원은 현재 저장소에 적용됩니다.</p><button v-if="mode==='cloud'" class="btn secondary small" :disabled="busy" @click="signOut().catch(report)">이 기기에서 로그아웃</button></section><section class="settings-section"><h2>간격 복습</h2><p>복습은 지정 학습 문제 수와 별도로 출제합니다.</p><label>한 학습 세션의 복습 상한<select :disabled="!ready||busy" :value="state.reviewQuestionLimit" @change="setReviewQuestionLimit(Number(($event.target as HTMLSelectElement).value)).catch(report)"><option v-for="n in [3,5,8,10]" :key="n" :value="n">최대 {{n}}문제</option></select></label><p class="muted footnote">첫 오답은 다음 새 학습 세션에 나와요. 복습에서 맞히면 3회차 뒤 확인하고 다시 맞히면 일반 출제 후보가 돼요. 휴식일은 회차에 포함하지 않아요.</p></section><section class="settings-section"><h2>백업과 복원</h2><p>브라우저 데이터를 지우거나 기기를 바꾸기 전에 백업해 주세요.</p><div class="backup-actions"><button class="btn secondary" :disabled="!ready||busy" @click="exportData"><AppIcon name="download" :size="18"/>JSON 내보내기</button><label class="btn secondary file-button">JSON 가져오기<input type="file" :disabled="!ready||busy" accept=".json,application/json" @change="chooseFile"></label></div><div v-if="pending" class="import-confirm"><p>학습 기록 {{pending.sessions.length}}개를 가져와 <b>현재 저장소의 데이터를 교체</b>합니다.</p><button class="btn small" :disabled="!ready||busy" @click="importData">교체하여 가져오기</button><button class="btn ghost small" @click="pending=null">취소</button></div><p class="muted footnote">스키마 버전 2 · 최대 10MB · {{state.sessions.length}}개의 학습 기록</p></section><section class="settings-section"><h2>데이터 삭제</h2><p>현재 저장소의 계획과 학습 기록을 모두 삭제해요. 이 작업은 되돌릴 수 없어요.</p><label class="delete-confirm">확인을 위해 ‘삭제’를 입력해 주세요.<input v-model="confirmDelete" placeholder="삭제" autocomplete="off"></label><button class="btn danger small" :disabled="!ready||confirmDelete!=='삭제'||busy" @click="deleteData">현재 저장소 데이터 삭제</button></section></div></template>
